use tree_sitter::Parser;
fn dump(node: tree_sitter::Node, src: &str, depth: usize) {
    let indent = "  ".repeat(depth);
    let text = &src[node.start_byte()..node.end_byte()];
    let t = text.replace('\n', "\\n");
    let named = if node.is_named() { "" } else { " (anon)" };
    let is_error = if node.is_error() || node.is_missing() { " <-- ERR/MISS" } else { "" };
    let truncated = if t.len() > 44 { format!("{}...", &t[..44]) } else { t };
    println!("{indent}{} {:?}{}{}", node.kind(), truncated, named, is_error);
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) { dump(child, src, depth + 1); }
}
fn main() {
    let samples = vec![
        // properties block attributes
        "classdef MyClass\n  properties (Constant, Dependent)\n    x\n  end\nend\n",
        "classdef MyClass\n  properties (Static)\n    x\n  end\nend\n",
        "classdef MyClass\n  properties (Visible)\n    x\n  end\nend\n",
        "classdef MyClass\n  properties (Constant)\n    x\n  end\n  methods\n    function v = get.x(obj)\n      v = 1;\n    end\n  end\nend\n",
        // name-value options
        "d = dsp.VariableIntegerDelay('DirectFeedthrough', true);\n",
        "f = fitsread('file.fits', 'SamplingRate', 100);\n",
        "obj = SomeClass('FilterSpecification', 'Auto');\n",
        "x = raytrace('NumReflections', 3);\n",
        "features('UseHG2');\n",
        "opt = optimoptions('fmincon', 'InitialHessType', 'bfgs');\n",
    ];
    let mut parser = Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    for (i, s) in samples.iter().enumerate() {
        let tree = parser.parse(s, None).unwrap();
        println!("===== {i}: {s:?} =====");
        dump(tree.root_node(), s, 0);
        println!();
    }
}
